class Solution {
    int find(vector<int>& parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

public:
    int minimumHammingDistance(vector<int>& source, vector<int>& target, vector<vector<int>>& allowedSwaps) {
        int n = source.size();
        vector<int> parent(n);
        for (int i = 0; i < n; i++) parent[i] = i;

        for (auto& sw : allowedSwaps) {
            int pa = find(parent, sw[0]), pb = find(parent, sw[1]);
            if (pa != pb) parent[pa] = pb;
        }

        unordered_map<int, vector<int>> components;
        for (int i = 0; i < n; i++) {
            components[find(parent, i)].push_back(i);
        }

        int hamming = 0;
        for (auto& [root, indices] : components) {
            unordered_map<int, int> sourceFreq, targetFreq;
            for (int idx : indices) {
                sourceFreq[source[idx]]++;
                targetFreq[target[idx]]++;
            }
            int common = 0;
            for (auto& [val, cnt] : sourceFreq) {
                auto it = targetFreq.find(val);
                if (it != targetFreq.end()) {
                    common += min(cnt, it->second);
                }
            }
            hamming += (int)indices.size() - common;
        }

        return hamming;
    }
};
